const $=id=>document.getElementById(id);const canvas=$('canvas'),ctx=canvas.getContext('2d');
let original=null,cutout=null,hand=null,busy=false,editing=false,tool='crop',drawing=false,selection=null,history=[],count=0;
let pointer={x:430,y:280},previous=null,pressed=false,energy=0,phase=0,autoUntil=0,bg='#c9f76b';
const makeCanvas=(w,h)=>{const c=document.createElement('canvas');c.width=w;c.height=h;return c};
const clone=c=>{const n=makeCanvas(c.width,c.height);n.getContext('2d').drawImage(c,0,0);return n};
const status=s=>$('status').textContent=s;
function fit(){const max=editing?710:540;const scale=Math.min(max/cutout.width,(editing?710:530)/cutout.height);const w=cutout.width*scale,h=cutout.height*scale;return {x:(800-w)/2,y:editing?(800-h)/2:680-h,w,h,scale};}
function point(e){const r=canvas.getBoundingClientRect(),side=Math.min(r.width,r.height);return{x:(e.clientX-r.left-(r.width-side)/2)*800/side,y:(e.clientY-r.top-(r.height-side)/2)*800/side};}
function save(){history.push(clone(cutout));if(history.length>12)history.shift();$('undo').disabled=false;}
function setMode(v){editing=v;selection=null;$('editor-tools').hidden=!v;$('mode-label').textContent=v?'CHỈNH CHỦ THỂ':'SÂN KHẤU XOA XOA';$('hint').textContent=v?'Khoanh vùng chủ thể hoặc dùng cọ Xóa / Giữ lại.':'Giữ & rê chuột để xoa · Điện thoại: dùng ngón tay';pressed=false;}
async function loadImage(url){const img=new Image();img.src=url;await img.decode();return img;}
async function setImage(img){const scale=Math.min(1,1200/Math.max(img.width,img.height));original=makeCanvas(Math.round(img.width*scale),Math.round(img.height*scale));original.getContext('2d').drawImage(img,0,0,original.width,original.height);cutout=clone(original);history=[];count=0;$('counter').textContent='0 cái xoa';$('empty').hidden=true;$('undo').disabled=true;setMode(false);status('Ảnh đã sẵn sàng. Tách nền hoặc xoa ngay.');}
async function readFile(file){if(!file||busy)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)){status('Hãy chọn ảnh JPG, PNG hoặc WEBP.');return;}if(file.size>20*1024*1024){status('Ảnh quá lớn. Chọn ảnh dưới 20 MB.');return;}const url=URL.createObjectURL(file);try{await setImage(await loadImage(url));}catch{status('Không đọc được ảnh. Hãy thử một ảnh khác.');}finally{URL.revokeObjectURL(url);}}
$('file').onchange=e=>{readFile(e.target.files[0]);e.target.value='';};$('capture').onchange=e=>{readFile(e.target.files[0]);e.target.value='';};$('camera').onclick=()=>$('capture').click();$('dropzone').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('file').click();}};
for(const name of ['dragenter','dragover'])$('dropzone').addEventListener(name,e=>{e.preventDefault();$('dropzone').classList.add('drag');});for(const name of ['dragleave','drop'])$('dropzone').addEventListener(name,e=>{e.preventDefault();$('dropzone').classList.remove('drag');if(name==='drop')readFile(e.dataTransfer.files[0]);});
async function demo(){if(busy)return;try{await setImage(await loadImage('cat.png'));status('Mèo mẫu đã tách nền. Giữ và rê chuột để xoa!');}catch{status('Chọn ảnh của bạn để bắt đầu.');}}$('demo').onclick=demo;
$('edit').onclick=()=>{if(busy)return;if(!cutout){status('Chọn một ảnh trước nhé.');return;}setMode(!editing);};$('done').onclick=()=>setMode(false);
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{tool=b.dataset.tool;selection=null;document.querySelectorAll('[data-tool]').forEach(x=>x.classList.toggle('selected',x===b));});
$('undo').onclick=()=>{if(history.length){cutout=history.pop();selection=null;$('undo').disabled=!history.length;}};
$('applycrop').onclick=()=>{if(!selection){status('Kéo một hình chữ nhật quanh chủ thể trước.');return;}const f=fit();const x=Math.max(0,Math.floor((Math.min(selection.a.x,selection.b.x)-f.x)/f.scale)),y=Math.max(0,Math.floor((Math.min(selection.a.y,selection.b.y)-f.y)/f.scale));const r=Math.min(cutout.width,Math.ceil((Math.max(selection.a.x,selection.b.x)-f.x)/f.scale)),b=Math.min(cutout.height,Math.ceil((Math.max(selection.a.y,selection.b.y)-f.y)/f.scale));if(r-x<10||b-y<10){status('Vùng chọn quá nhỏ hoặc nằm ngoài ảnh.');return;}const crop=c=>{const n=makeCanvas(r-x,b-y);n.getContext('2d').drawImage(c,x,y,r-x,b-y,0,0,r-x,b-y);return n};cutout=crop(cutout);original=crop(original);history=[];$('undo').disabled=true;selection=null;status('Đã giữ vùng chọn. Bấm tách nền để xử lý chủ thể này.');};
function brush(p){const f=fit(),x=(p.x-f.x)/f.scale,y=(p.y-f.y)/f.scale,r=Number($('brush').value)/f.scale;const c=cutout.getContext('2d');c.save();c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.clip();if(tool==='erase'){c.clearRect(x-r,y-r,r*2,r*2);}else c.drawImage(original,0,0);c.restore();}
canvas.onpointerdown=e=>{if(!cutout||busy)return;e.preventDefault();canvas.focus({preventScroll:true});canvas.setPointerCapture(e.pointerId);pointer=point(e);previous=pointer;if(editing){drawing=true;if(tool==='crop')selection={a:pointer,b:pointer};else{save();brush(pointer);}}else{pressed=true;energy=.7;count++;$('counter').textContent=count+' cái xoa';}};
canvas.onpointermove=e=>{const p=point(e);if(drawing&&editing){if(tool==='crop')selection.b=p;else{const d=Math.hypot(p.x-previous.x,p.y-previous.y),n=Math.max(1,Math.ceil(d/4));for(let i=1;i<=n;i++)brush({x:previous.x+(p.x-previous.x)*i/n,y:previous.y+(p.y-previous.y)*i/n});}}else if(pressed){const d=Math.hypot(p.x-pointer.x,p.y-pointer.y);energy=Math.min(1,energy+d*.012);}pointer=p;previous=p;};
function release(){pressed=false;drawing=false;previous=null;}canvas.onpointerup=release;canvas.onpointercancel=release;canvas.onlostpointercapture=release;window.addEventListener('blur',release);
function pet(){if(!cutout||busy){status('Chọn ảnh trước khi xoa nhé.');return;}setMode(false);autoUntil=performance.now()+1500;count++;$('counter').textContent=count+' cái xoa';} $('pet').onclick=pet;canvas.onkeydown=e=>{if(e.code==='Space'){e.preventDefault();if(!e.repeat)pet();}};
$('soft').oninput=()=>$('soft-value').textContent=$('soft').value+'%';document.querySelectorAll('[data-bg]').forEach(b=>b.onclick=()=>{bg=b.dataset.bg;$('stage').style.background=bg;document.querySelectorAll('[data-bg]').forEach(x=>x.classList.toggle('active',x===b));});
$('remove').onclick=async()=>{if(!cutout||busy){status('Chọn ảnh trước khi tách nền nhé.');return;}busy=true;$('remove').disabled=true;status('Đang tải bộ tách nền… lần đầu có thể mất 30–90 giây.');try{const {removeBackground}=await import('https://esm.sh/@imgly/background-removal@1.7.0');const input=await new Promise(r=>cutout.toBlob(r,'image/png'));const blob=await removeBackground(input,{model:'isnet_quint8',device:'cpu',proxyToWorker:false,progress:(key,current,total)=>{status(key.includes('fetch')?'Đang tải bộ tách nền… '+(total?Math.round(current/total*100)+'%':''):'Đang tách chủ thể…');}});const url=URL.createObjectURL(blob);try{const img=await loadImage(url);save();cutout=makeCanvas(img.width,img.height);cutout.getContext('2d').drawImage(img,0,0);}finally{URL.revokeObjectURL(url);}setMode(false);status('Đã tách nền. Nếu còn sót, mở sửa bằng cọ để chỉnh.');}catch(error){console.error(error);status('Chưa tải được bộ tách nền. Kiểm tra mạng và thử lại, hoặc dùng cọ Xóa để sửa thủ công.');}finally{busy=false;$('remove').disabled=false;}};
function frame(t){ctx.clearRect(0,0,800,800);if(cutout){const f=fit();const auto=t<autoUntil;if(auto){pointer={x:435+Math.sin(t*.012)*85,y:f.y+65};energy=.8;}energy*=pressed?.97:.9;phase+=.22;ctx.save();if(!editing){const squash=energy*(Number($('soft').value)/100)*(.12+.08*Math.abs(Math.sin(phase)));ctx.translate(400,680);ctx.transform(1+squash*.5,0,Math.sin(phase)*energy*.025,1-squash,0,0);ctx.drawImage(cutout,f.x-400,f.y-680,f.w,f.h);}else{for(let y=0;y<800;y+=20)for(let x=0;x<800;x+=20){ctx.fillStyle=(x+y)%40?'#edf0e8':'#ffffff';ctx.fillRect(x,y,20,20);}ctx.drawImage(cutout,f.x,f.y,f.w,f.h);}ctx.restore();if(editing&&selection){const {a,b}=selection;ctx.strokeStyle='#5945db';ctx.lineWidth=3;ctx.setLineDash([8,6]);ctx.strokeRect(a.x,a.y,b.x-a.x,b.y-a.y);ctx.setLineDash([]);ctx.fillStyle='#5945db22';ctx.fillRect(a.x,a.y,b.x-a.x,b.y-a.y);}if(!editing&&hand){const w=Number($('handsize').value)*5,h=w*hand.height/hand.width;const x=pressed||auto?pointer.x:440,y=pressed||auto?pointer.y:f.y+35;ctx.save();ctx.translate(x,y+Math.sin(phase)*energy*12);ctx.rotate(-.07+Math.sin(phase)*energy*.04);ctx.drawImage(hand,-w*.78,-h*.85,w,h);ctx.restore();}}requestAnimationFrame(frame);}requestAnimationFrame(frame);
loadImage('hand.png').then(img=>hand=img).catch(()=>status('Bàn tay đang được chuẩn bị. Bạn vẫn có thể chọn ảnh.'));demo();
const mc=document.modelContext;if(mc?.registerTool){try{Promise.resolve(mc.registerTool({name:'pet_image',description:'Play a short petting animation on the currently loaded image.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||Object.keys(input).length)throw new Error('Expected an empty object');if(!cutout||busy)throw new Error('No image ready');pet();return {started:true,pets:count};}})).catch(()=>{});}catch{}}
const cameraDialog=document.createElement('dialog');cameraDialog.className='camera-dialog';cameraDialog.setAttribute('aria-label','Chụp ảnh chủ thể');cameraDialog.innerHTML='<h2>Chụp nhân vật của bạn</h2><video autoplay playsinline muted></video><p role="status">Đang mở máy ảnh…</p><div class="row"><button class="secondary" data-close>Đóng</button><button class="primary" data-snap disabled>Chụp ảnh</button></div>';document.body.append(cameraDialog);
let stream=null,cameraSession=0;const video=cameraDialog.querySelector('video'),cameraStatus=cameraDialog.querySelector('p'),snap=cameraDialog.querySelector('[data-snap]');
function closeCamera(){cameraSession++;stream?.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;cameraDialog.close();}
cameraDialog.querySelector('[data-close]').onclick=closeCamera;cameraDialog.addEventListener('cancel',e=>{e.preventDefault();closeCamera();});
$('camera').onclick=async()=>{if(busy)return;if(!navigator.mediaDevices?.getUserMedia){$('capture').click();return;}const session=++cameraSession;cameraDialog.showModal();snap.disabled=true;cameraStatus.textContent='Cho phép dùng máy ảnh để chụp. Ảnh chỉ xử lý trên thiết bị.';try{const next=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280}},audio:false});if(session!==cameraSession){next.getTracks().forEach(t=>t.stop());return;}stream=next;video.srcObject=stream;await video.play();snap.disabled=false;cameraStatus.textContent='Đưa chủ thể vào khung hình, rồi bấm Chụp ảnh.';}catch{cameraStatus.textContent='Không mở được máy ảnh. Kiểm tra quyền truy cập hoặc đóng và chọn ảnh có sẵn.';}};
snap.onclick=async()=>{if(!video.videoWidth)return;const photo=makeCanvas(video.videoWidth,video.videoHeight);photo.getContext('2d').drawImage(video,0,0);closeCamera();await setImage(photo);};

